"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useState } from "react";

const SNAPS = [0.45, 0.88];

export function BottomSheetTailwind() {
  const [open, setOpen] = useState(false);
  const [snap, setSnap] = useState(0);
  const [vh, setVh] = useState(800);
  useEffect(() => {
    if (!open) return;
    setVh(window.innerHeight);
    setSnap(0);
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open]);
  const max = SNAPS[SNAPS.length - 1] * vh;
  const offset = (i: number) => max - SNAPS[i] * vh;
  return (
    <>
      <button onClick={() => setOpen(true)} className="h-9 rounded-lg border border-zinc-800 bg-zinc-900 px-4 text-sm font-medium text-zinc-100">Share project</button>
      <AnimatePresence>
        {open && (
          <div className="fixed inset-0 z-50">
            <motion.div className="absolute inset-0 bg-black/50" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setOpen(false)} />
            <motion.div role="dialog" aria-modal="true" aria-label="Share project" style={{ height: max }} className="absolute inset-x-0 bottom-0 mx-auto max-w-xl rounded-t-2xl border border-zinc-800 bg-zinc-950 px-5 text-zinc-100"
              initial={{ y: max }} animate={{ y: offset(snap) }} exit={{ y: max }} transition={{ type: "spring", stiffness: 420, damping: 42 }}
              drag="y" dragConstraints={{ top: 0, bottom: max }} dragElastic={0.1}
              onDragEnd={(_, info) => {
                const projected = offset(snap) + info.offset.y + info.velocity.y * 0.2;
                if (projected > offset(0) + 120) return setOpen(false);
                setSnap(Math.abs(projected - offset(0)) < Math.abs(projected - offset(1)) ? 0 : 1);
              }}>
              <button aria-label={snap ? "Collapse sheet" : "Expand sheet"} onClick={() => setSnap(snap ? 0 : 1)} className="mx-auto my-2 flex h-6 w-16 items-center justify-center"><span className="h-1.5 w-10 rounded-full bg-zinc-600" /></button>
              <h2 className="text-lg font-semibold">Share project</h2>
              <p className="text-sm text-zinc-400">Drag the handle to resize.</p>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}
